.mage-scene .mage-card{margin-bottom:12px}
.mage-scene .mage-card-facing{position:absolute;top:calc(100% + 2px);left:calc(50% - 5px);width:10px;height:10px;pointer-events:none}
.mage-scene .mage-card-facing svg{display:block;width:100%;height:100%;transform:rotate(var(--mage-bearing));transform-origin:center}
.mage-scene .mage-phase-card{position:relative;margin-bottom:16px}

/* The shrinking rim remains visible above every terrain illustration. */
.mage-scene .mage-risk::after{content:"";position:absolute;inset:0;border-radius:inherit;background:#d83c3680;pointer-events:none;animation:mage-risk-pulse 2.4s ease-in-out infinite}
@keyframes mage-risk-pulse{0%,100%{opacity:.4}50%{opacity:.85}}
.mage-scene .mage-token.is-selected{outline-offset:2px!important;--color-interaction-selected:#dfb83d}
.mage-scene .mage-preview{outline-color:color-mix(in srgb,var(--mage-selected) var(--piece-highlight-strength),transparent)}
.mage-scene [data-score-id="kills"]::before,.result-scores[data-game="mage-brawl"] [data-score-id="kills"]::before{content:"⚔";margin-right:3px}

@media(prefers-reduced-motion:reduce){.mage-scene .mage-risk::after{animation:none;opacity:.65}}

.mage-scene .mage-cell.is-playable{outline:var(--mage-cell-outline) solid var(--piece-interaction-color);outline-offset:calc(-1*var(--mage-cell-outline))!important}

.mage-scene .mage-token-health{position:absolute;bottom:24%;left:50%;transform:translateX(-50%);z-index:4;width:50%;height:auto;aspect-ratio:3;overflow:visible}
.mage-scene .piece-indicator{fill:#fff;stroke:#fff;stroke-width:1.2}
.mage-scene .piece-indicator.is-empty{fill:var(--mage-color)}

/* Narrow landscape side panel: controls use height, leaving the full width to cards. */
@media(orientation:landscape){
 .mage-scene .mage-hand-toolbar{flex-direction:column;gap:6px}
 .mage-scene .mage-hand-toolbar .mage-controls{order:-1;width:100%;justify-content:space-evenly}
 .mage-scene .mage-action-switch{flex:none;width:100%}
 .mage-scene .mage-hand-row{grid-template-columns:1fr 1fr;gap:4px 0}
 .mage-scene .mage-hand-row>.mage-rotate:first-child{grid-column:1;grid-row:1;justify-self:start}
 .mage-scene .mage-hand-row>.mage-rotate:last-child{grid-column:2;grid-row:1;justify-self:end}
 .mage-scene .mage-hand-row>section{grid-column:1 / -1;grid-row:2}
}

.mage-scene .mage-plan-preview{z-index:5;opacity:.72;pointer-events:none}
.mage-scene .mage-plan-locked{--piece-interaction-color:#638658;outline-color:#638658!important;opacity:1}
.mage-scene .mage-plan-order{position:absolute;top:2px;left:2px;border-radius:50%;background:#638658;color:white;width:16px;height:16px;font-size:11px;line-height:16px;z-index:4}
.mage-scene .mage-reset-plan{width:32px;height:32px;min-height:32px;padding:5px}

.mage-scene .mage-reset-plan{flex:none}
.mage-scene .mage-reset-plan:disabled{color:#899188;background:#e1e4dc;opacity:.6;box-shadow:none}
@media(orientation:landscape){
 .mage-scene .mage-hand-toolbar:has(.mage-reset-plan){display:grid;grid-template-columns:repeat(3,minmax(0,1fr));align-items:center;justify-items:center}
 .mage-scene .mage-hand-toolbar:has(.mage-reset-plan) .mage-controls{display:contents}
 .mage-scene .mage-hand-toolbar:has(.mage-reset-plan)>.mage-reset-plan{grid-column:1;grid-row:1}
 .mage-scene .mage-hand-toolbar:has(.mage-reset-plan) .mage-ready{grid-column:2;grid-row:1}
 .mage-scene .mage-hand-toolbar:has(.mage-reset-plan) [data-command="card-help"]{grid-column:3;grid-row:1}
 .mage-scene .mage-hand-toolbar:has(.mage-reset-plan)>.mage-action-switch{grid-column:1 / -1;grid-row:2}
}

.mage-action-switch button{position:relative}
.mage-action-switch .shared-action-marker{position:absolute;right:4px;top:2px;display:grid;place-items:center;width:1.1em;height:1.1em;border-radius:50%;background:#dcebc6;color:#315b43;border:1px solid #638765;font-size:.75em;font-weight:700}

/* A committed action keeps its fixed bearing when the remaining hand rotates. */
.mage-scene .mage-plan-locked .mage-spell-paint{transition:none}

/* Public action order; the same glyphs are used in the hand and help. */
.mage-order-hint{display:flex;align-items:center;justify-content:center;gap:8px;color:var(--ink,#29483e);font-size:14px;width:100%;padding:0}
.mage-order-group{display:flex;align-items:center;gap:5px}.mage-order-item{display:flex;align-items:center;justify-content:center;flex-direction:column;gap:4px;flex:none}.mage-order-item>svg{width:21px;height:21px;display:block}.mage-order-divider{height:20px;width:1px;background:currentColor;opacity:.25}.mage-order-arrow{opacity:.5;font-size:14px}.mage-order-hint.is-expanded{flex-wrap:wrap;gap:12px;padding:12px 0}.mage-order-hint.is-expanded .mage-order-item>svg{width:24px;height:24px}.mage-order-hint.is-expanded small{font-size:11px}.mage-order-hint.is-expanded .mage-order-group{gap:6px}.mage-order-hint.is-expanded .mage-order-divider{display:none}
.mage-scene .mage-hand{gap:2px}.mage-scene .mage-action-switch .mage-movement-icon{width:24px;height:24px}

.mage-scene>.layout-auxiliary{display:none}
@media(max-width:480px){.mage-order-hint.is-expanded{flex-direction:column}}


/* Compact controls keep the same dimensions in both orientations. */
.mage-scene{--square-hand-padding:4px 6px 0}
.mage-scene .mage-hand-toolbar{gap:4px;--ui-control-size:32px;--ui-target:32px}
.mage-scene .mage-hand-toolbar .mage-controls .mage-ready,.mage-scene .mage-hand-toolbar .mage-controls [data-command="card-help"],.mage-scene .mage-hand-toolbar>.mage-reset-plan{width:32px;height:32px;min-height:32px;padding:6px}
.mage-scene .mage-hand-toolbar .mage-controls svg,.mage-scene .mage-reset-plan svg{width:20px;height:20px}
.mage-scene .mage-action-switch .shared-page-tabs{padding:2px;border-radius:12px}
.mage-scene .mage-action-switch .shared-page-tabs::before{inset:2px auto 2px 2px;width:calc((100% - 4px)/var(--page-count,2));border-radius:10px}
.mage-scene .mage-action-switch button{height:26px;min-height:26px;padding:2px 4px}
.mage-scene .mage-action-switch svg,.mage-scene .mage-action-switch .mage-movement-icon{width:20px;height:20px}

/* Keep direction arrows legible over filled shields and target cells. */
.mage-action-diagram .mage-diagram-arrow path{stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
.mage-action-diagram .mage-diagram-arrow .mage-diagram-arrow-halo path{stroke:var(--color-surface-raised,#fffbed);stroke-width:4.5}

/* Rings share board tracks, above art and effects, without extending into neighbours. */
.mage-scene .mage-grid>.mage-cell{outline:none!important;border-radius:0}
.mage-scene .mage-highlights{position:absolute;inset:0;display:grid;grid-template-columns:inherit;grid-template-rows:inherit;gap:inherit;z-index:8;pointer-events:none}
.mage-scene .mage-cell-highlight{min-width:0;min-height:0;box-sizing:border-box;--mage-ring:max(2px,calc((100cqi - (var(--mage-columns) - 1)*2px)/var(--mage-columns)*.05))}
.mage-scene .mage-cell-highlight.is-preview{border:var(--mage-ring) solid color-mix(in srgb,var(--mage-selected) var(--piece-highlight-strength,100%),transparent)}
.mage-scene .mage-cell-highlight.is-respawn{border:var(--mage-ring) solid var(--piece-interaction-color,#638658)}
.mage-scene .mage-cell-highlight.is-acting{border:var(--mage-ring) solid #fffbed}

.mage-scene .mage-cell-highlight.is-preview.is-attack-preview{--mage-ring:max(3px,calc((100cqi - (var(--mage-columns) - 1)*2px)/var(--mage-columns)*.075))}
